// Definition for a binary tree node.
class Node {
    int data;
    Node left;
    Node right;
    Node(int data) { this.data = data; }
}

public int height(Node root) {
    if (root == null) return -1;                    // null contributes -1 edge
    int leftHeight = height(root.left);             // children report first
    int rightHeight = height(root.right);
    return 1 + Math.max(leftHeight, rightHeight);   // +1 edge to this node
}

public int height(Node root) {
    if (root == null) return -1;            // empty tree: -1 edges
    Queue<Node> queue = new LinkedList<>();
    queue.offer(root);
    int levels = 0;
    while (!queue.isEmpty()) {
        int levelSize = queue.size();       // snapshot this level
        for (int i = 0; i < levelSize; i++) {
            Node node = queue.poll();
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        levels++;                           // one full level drained
    }
    return levels - 1;                      // levels (nodes-deep) -> edges
}

