from collections import deque

def height(root: Node) -> int:
    if root is None:
        return -1
    queue = deque([root])
    levels = 0
    while queue:
        for _ in range(len(queue)):         # snapshot this level
            node = queue.popleft()
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        levels += 1                         # one full level drained
    return levels - 1                       # convert nodes-deep to edges

